/* formatPieceLabel (views/analysis.js) combines a piece's autogenerated id with its original upload filename so multiple loaded pieces can
 * be told apart in the piece list, upload confirmation, and piece detail heading -- the id alone (e.g. "piece-1788837459-41") gives no
 * clue which uploaded file it came from. Plain Node script, run through ctest. */
import { formatPieceLabel } from "../public/views/analysis.js";
import { check, finish } from "./support/check.js";

check(
  formatPieceLabel("piece-1788837459-41", "sonata.mid") === "sonata.mid (piece-1788837459-41)",
  "combines filename and id when a filename is present",
);
check(
  formatPieceLabel("piece-1788837459-41", "") === "piece-1788837459-41",
  "falls back to the bare id when the filename is empty",
);
check(
  formatPieceLabel("piece-1788837459-41", undefined) === "piece-1788837459-41",
  "falls back to the bare id when the filename is missing",
);

finish();
